package ua.malinapk.birthdays;
import java.io.*;import java.util.*;import java.util.zip.*;import java.time.*;import java.time.format.*;
import javax.xml.parsers.*;import javax.xml.transform.*;import javax.xml.transform.dom.*;import javax.xml.transform.stream.*;import org.w3c.dom.*;
final class Workbook {
 static final String NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
 static final LocalDate EPOCH=LocalDate.of(1899,12,30);
 final LinkedHashMap<String,byte[]> files=new LinkedHashMap<>(); final Document sheet; final Element data; final List<String> shared=new ArrayList<>(); final List<Person> people=new ArrayList<>();
 static byte[] bytes(InputStream in) throws IOException {try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){out.write(b,0,n);if(out.size()>25_000_000)throw new IOException("Файл завеликий");}return out.toByteArray();}}
 static Document xml(byte[] b)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);if(new String(b,java.nio.charset.StandardCharsets.UTF_8).contains("<!DOCTYPE"))throw new IOException("DOCTYPE заборонено");try{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);}catch(ParserConfigurationException ignored){}return f.newDocumentBuilder().parse(new ByteArrayInputStream(b));}
 static String text(Element e,String tag){NodeList list=e.getElementsByTagNameNS(NS,tag);StringBuilder b=new StringBuilder();for(int i=0;i<list.getLength();i++)b.append(list.item(i).getTextContent());return b.toString();}
 Workbook(byte[] raw)throws Exception{
  long total=0;try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(raw))){ZipEntry e;while((e=z.getNextEntry())!=null){if(e.isDirectory())continue;ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=z.read(b))!=-1){total+=n;if(total>40_000_000)throw new IOException("Файл завеликий");o.write(b,0,n);}files.put(e.getName(),o.toByteArray());}}
  if(!files.containsKey("xl/worksheets/sheet1.xml"))throw new IOException("Потрібен Excel формату XLSX");
  if(files.containsKey("xl/sharedStrings.xml")){NodeList l=xml(files.get("xl/sharedStrings.xml")).getElementsByTagNameNS(NS,"si");for(int i=0;i<l.getLength();i++)shared.add(text((Element)l.item(i),"t"));}
  sheet=xml(files.get("xl/worksheets/sheet1.xml"));data=(Element)sheet.getElementsByTagNameNS(NS,"sheetData").item(0);
  if(data==null)throw new IOException("Немає таблиці");boolean header=false;NodeList rows=data.getElementsByTagNameNS(NS,"row");
  for(int i=0;i<rows.getLength();i++){Element r=(Element)rows.item(i);int row=Integer.parseInt(r.getAttribute("r"));String[] a=values(r);
   if(row==1){header=a[0].equalsIgnoreCase("Прізвище")&&a[3].equalsIgnoreCase("Посада")&&a[4].equalsIgnoreCase("Підрозділ")&&a[5].equalsIgnoreCase("Дата народження");continue;}
   if(a[0].isEmpty())continue;try{LocalDate d=date(a[5]);people.add(new Person(row,a[0],a[1],a[2],a[3],a[4],d));}catch(Exception ex){throw new IOException("Некоректна дата народження в рядку "+row);}
  }if(!header)throw new IOException("Структура не відповідає файлу Іменинники.xlsx");
 }
 String[] values(Element r){String[] a={"","","","","",""};NodeList cells=r.getElementsByTagNameNS(NS,"c");for(int i=0;i<cells.getLength();i++){Element c=(Element)cells.item(i);String ref=c.getAttribute("r");if(ref.isEmpty()||ref.length()<2||!Character.isDigit(ref.charAt(1)))continue;int k=ref.charAt(0)-'A';if(k<0||k>=6)continue;String v=text(c,"v");String t=c.getAttribute("t");if(t.equals("s")&&!v.isEmpty())v=shared.get(Integer.parseInt(v));if(t.equals("inlineStr"))v=text(c,"t");a[k]=v.trim();}return a;}
 static LocalDate date(String s){try{return EPOCH.plusDays((long)Double.parseDouble(s));}catch(Exception ignored){}try{return LocalDate.parse(s);}catch(Exception ignored){}return LocalDate.parse(s,DateTimeFormatter.ofPattern("d.M.uuuu"));}
 Element row(int n){NodeList rows=data.getElementsByTagNameNS(NS,"row");for(int i=0;i<rows.getLength();i++){Element r=(Element)rows.item(i);if(Integer.parseInt(r.getAttribute("r"))==n)return r;}return null;}
 Element cell(Element row,int n,int k){String ref=String.valueOf((char)('A'+k))+n;NodeList cs=row.getElementsByTagNameNS(NS,"c");for(int i=0;i<cs.getLength();i++){Element c=(Element)cs.item(i);if(ref.equals(c.getAttribute("r")))return c;}Element c=sheet.createElementNS(NS,"c");c.setAttribute("r",ref);for(int i=0;i<cs.getLength();i++){Element old=(Element)cs.item(i);if(old.getAttribute("r").charAt(0)>ref.charAt(0)){row.insertBefore(c,old);return c;}}row.appendChild(c);return c;}
 void setDirectory(int n,boolean job,String value)throws IOException{
  Element r=row(n);if(r==null)throw new IOException("Не знайдено рядок Excel: "+n);
  Element c=cell(r,n,job?3:4);while(c.hasChildNodes())c.removeChild(c.getFirstChild());c.setAttribute("t","inlineStr");Element is=sheet.createElementNS(NS,"is"),t=sheet.createElementNS(NS,"t");t.setTextContent(value);is.appendChild(t);c.appendChild(is);
 }
 void put(Person p,boolean delete)throws Exception{
  int n=p.row;if(n<=1){n=2;for(Person q:people)n=Math.max(n,q.row+1);}Element r=row(n);if(delete){if(r!=null)data.removeChild(r);return;}if(r==null){r=sheet.createElementNS(NS,"row");r.setAttribute("r",""+n);r.setAttribute("spans","1:6");NodeList rs=data.getElementsByTagNameNS(NS,"row");Node before=null;for(int i=0;i<rs.getLength();i++)if(Integer.parseInt(((Element)rs.item(i)).getAttribute("r"))>n){before=rs.item(i);break;}data.insertBefore(r,before);}
  String[] a={p.last,p.first,p.middle,p.job,p.unit};String[] styles={"3","4","4","5","6","7"};for(int k=0;k<6;k++){Element c=cell(r,n,k);while(c.hasChildNodes())c.removeChild(c.getFirstChild());if(!c.hasAttribute("s")||k==5)c.setAttribute("s",styles[k]);if(k<5){c.setAttribute("t","inlineStr");Element is=sheet.createElementNS(NS,"is"),t=sheet.createElementNS(NS,"t");t.setTextContent(a[k]);is.appendChild(t);c.appendChild(is);}else{c.removeAttribute("t");Element v=sheet.createElementNS(NS,"v");v.setTextContent(Long.toString(java.time.temporal.ChronoUnit.DAYS.between(EPOCH,p.born)));c.appendChild(v);}}
  Element dim=(Element)sheet.getElementsByTagNameNS(NS,"dimension").item(0);if(dim!=null){int max=n;NodeList rs=data.getElementsByTagNameNS(NS,"row");for(int i=0;i<rs.getLength();i++)max=Math.max(max,Integer.parseInt(((Element)rs.item(i)).getAttribute("r")));dim.setAttribute("ref","A1:F"+max);}
 }
 static double exportWidth(String value){int longest=0;for(String line:value.split("\\R",-1))longest=Math.max(longest,line.codePointCount(0,line.length()));return Math.min(255,Math.max(12,Math.ceil(longest*1.35+4)));}
 static byte[] xmlBytes(Document doc)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();TransformerFactory.newInstance().newTransformer().transform(new DOMSource(doc),new StreamResult(out));return out.toByteArray();}
 byte[] formattedExport()throws Exception{
  // The caller constructs a fresh Workbook; only the exported copy is changed.
  Document styles=xml(files.get("xl/styles.xml"));Element borders=(Element)styles.getElementsByTagNameNS(NS,"borders").item(0),xfs=(Element)styles.getElementsByTagNameNS(NS,"cellXfs").item(0);
  int borderId=borders.getElementsByTagNameNS(NS,"border").getLength();Element border=styles.createElementNS(NS,"border");for(String side:new String[]{"left","right","top","bottom"}){Element edge=styles.createElementNS(NS,side);edge.setAttribute("style","thin");Element color=styles.createElementNS(NS,"color");color.setAttribute("rgb","FF808080");edge.appendChild(color);border.appendChild(edge);}border.appendChild(styles.createElementNS(NS,"diagonal"));borders.appendChild(border);borders.setAttribute("count",Integer.toString(borderId+1));
  int originalStyles=xfs.getElementsByTagNameNS(NS,"xf").getLength();Map<Integer,Integer> styleMap=new HashMap<>();double[] widths=new double[6];NodeList rows=data.getElementsByTagNameNS(NS,"row");
  for(int i=0;i<rows.getLength();i++){Element r=(Element)rows.item(i);int n=Integer.parseInt(r.getAttribute("r"));String[] a=values(r);if(n!=1&&a[0].isEmpty())continue;for(int k=0;k<6;k++){
   String displayed=k==5&&n!=1?date(a[k]).format(DateTimeFormatter.ofPattern("dd.MM.uuuu")):a[k];widths[k]=Math.max(widths[k],exportWidth(displayed));Element c=cell(r,n,k);int id=c.hasAttribute("s")?Integer.parseInt(c.getAttribute("s")):0;if(id<0||id>=originalStyles)id=0;
   Integer mapped=styleMap.get(id);if(mapped==null){Element xf=(Element)xfs.getElementsByTagNameNS(NS,"xf").item(id).cloneNode(true);xf.setAttribute("borderId",Integer.toString(borderId));xf.setAttribute("applyBorder","1");mapped=xfs.getElementsByTagNameNS(NS,"xf").getLength();xfs.appendChild(xf);styleMap.put(id,mapped);}c.setAttribute("s",Integer.toString(mapped));
  }}xfs.setAttribute("count",Integer.toString(xfs.getElementsByTagNameNS(NS,"xf").getLength()));
  Element root=sheet.getDocumentElement(),cols=(Element)root.getElementsByTagNameNS(NS,"cols").item(0);if(cols==null){cols=sheet.createElementNS(NS,"cols");root.insertBefore(cols,data);}List<Element> later=new ArrayList<>();NodeList old=cols.getElementsByTagNameNS(NS,"col");for(int i=0;i<old.getLength();i++){Element col=(Element)old.item(i);if(Integer.parseInt(col.getAttribute("max"))>6){Element copy=(Element)col.cloneNode(true);copy.setAttribute("min",Integer.toString(Math.max(7,Integer.parseInt(col.getAttribute("min")))));later.add(copy);}}while(cols.hasChildNodes())cols.removeChild(cols.getFirstChild());for(int k=0;k<6;k++){Element col=sheet.createElementNS(NS,"col");col.setAttribute("min",Integer.toString(k+1));col.setAttribute("max",Integer.toString(k+1));col.setAttribute("width",Double.toString(Math.max(12,widths[k])));col.setAttribute("customWidth","1");cols.appendChild(col);}for(Element col:later)cols.appendChild(col);
  files.put("xl/styles.xml",xmlBytes(styles));return save();
 }
 byte[] save()throws Exception{ByteArrayOutputStream xml=new ByteArrayOutputStream();TransformerFactory.newInstance().newTransformer().transform(new DOMSource(sheet),new StreamResult(xml));files.put("xl/worksheets/sheet1.xml",xml.toByteArray());ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){for(Map.Entry<String,byte[]> e:files.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}return out.toByteArray();}
}
